require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('activities.manage');$id=max(0,(int)($_GET['id']??$_POST['id']??0));$item=null;if($id){$s=db()->prepare('SELECT * FROM activities WHERE id=?');$s->execute([$id]);$item=$s->fetch();if(!$item){http_response_code(404);exit('Actividad no encontrada.');}}$pageTitle=$item?'Editar actividad':'Nueva actividad';$clients=db()->query('SELECT id,company_name FROM clients ORDER BY company_name')->fetchAll();$contacts=db()->query("SELECT id,client_id,TRIM(CONCAT(first_name,' ',COALESCE(last_name,''))) name FROM contacts WHERE status<>'inactive' ORDER BY first_name,last_name")->fetchAll();$deals=db()->query("SELECT id,client_id,title FROM deals WHERE status='open' ORDER BY title")->fetchAll();$users=db()->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();$errors=[];$v=fn(string$key,mixed$default='')=>$_POST[$key]??($item[$key]??$default);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=(string)($_POST['activity_type']??'task');$subject=trim((string)($_POST['subject']??''));$status=(string)($_POST['status']??'pending');$priority=(string)($_POST['priority']??'normal');if(!in_array($type,['task','event','call','email','meeting','note'],true))$type='task';if(!in_array($status,['pending','completed','cancelled'],true))$status='pending';if(!in_array($priority,['low','normal','high','urgent'],true))$priority='normal';if($subject==='')$errors[]='El asunto es obligatorio.';$due=trim((string)($_POST['due_at']??''));$due=$due!==''?date('Y-m-d H:i:s',strtotime($due)):null;$data=[max(0,(int)($_POST['client_id']??0))?:null,max(0,(int)($_POST['contact_id']??0))?:null,max(0,(int)($_POST['deal_id']??0))?:null,(int)$_SESSION['user_id'],max(0,(int)($_POST['assigned_to']??0))?:null,$type,$subject,trim((string)($_POST['details']??''))?:null,$due,$status==='completed'?date('Y-m-d H:i:s'):null,$status,$priority,trim((string)($_POST['meeting_url']??''))?:null];if(!$errors){if($id){db()->prepare('UPDATE activities SET client_id=?,contact_id=?,deal_id=?,created_by=?,assigned_to=?,activity_type=?,subject=?,details=?,due_at=?,completed_at=?,status=?,priority=?,meeting_url=? WHERE id=?')->execute([...$data,$id]);}else{db()->prepare('INSERT INTO activities(client_id,contact_id,deal_id,created_by,assigned_to,activity_type,subject,details,due_at,completed_at,status,priority,meeting_url) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($data);$id=(int)db()->lastInsertId();}log_activity($item?'Actividad actualizada':'Actividad creada',(int)($data[0]??0),null,$subject);flash('success','Actividad guardada.');$return=$data[2]?'deal_view.php?id='.$data[2]:($data[1]?'contact_view.php?id='.$data[1]:'activities.php');redirect($return);}}
