<?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2><?=$item?'Actualizar actividad':'Registrar actividad'?></h2><span class="table-sub">Tarea, evento, llamada, correo, reunión o nota.</span></div><a class="btn btn-light btn-small" href="activities.php">Volver</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Tipo<select name="activity_type"><?php foreach(['task','event','call','email','meeting','note']as$x):?><option value="<?=$x?>" <?=$v('activity_type','task')===$x?'selected':''?>><?=e(crm_activity_type_label($x))?></option><?php endforeach;?></select></label><label>Asunto *<input name="subject" required value="<?=e($v('subject'))?>"></label><label>Fecha y hora<input type="datetime-local" name="due_at" value="<?=e($v('due_at')?date('Y-m-d\TH:i',strtotime((string)$v('due_at'))):'')?>"></label><label>Cliente<select name="client_id"><option value="0">Sin cliente</option><?php foreach($clients as$c):?><option value="<?=$c['id']?>" <?=(int)$v('client_id',(int)($_GET['client_id']??0))===(int)$c['id']?'selected':''?>><?=e($c['company_name'])?></option><?php endforeach;?></select></label><label>Contacto<select name="contact_id"><option value="0">Sin contacto</option><?php foreach($contacts as$c):?><option value="<?=$c['id']?>" <?=(int)$v('contact_id',(int)($_GET['contact_id']??0))===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Negocio<select name="deal_id"><option value="0">Sin negocio</option><?php foreach($deals as$d):?><option value="<?=$d['id']?>" <?=(int)$v('deal_id',(int)($_GET['deal_id']??0))===(int)$d['id']?'selected':''?>><?=e($d['title'])?></option><?php endforeach;?></select></label><label>Asignar a<select name="assigned_to"><option value="0">Sin asignar</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=(int)$v('assigned_to',$_SESSION['user_id'])===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Prioridad<select name="priority"><?php foreach(['low'=>'Baja','normal'=>'Normal','high'=>'Alta','urgent'=>'Urgente']as$k=>$l):?><option value="<?=$k?>" <?=$v('priority','normal')===$k?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Estado<select name="status"><option value="pending" <?=$v('status','pending')==='pending'?'selected':''?>>Pendiente</option><option value="completed" <?=$v('status')==='completed'?'selected':''?>>Completada</option><option value="cancelled" <?=$v('status')==='cancelled'?'selected':''?>>Cancelada</option></select></label><label class="full">Enlace de reunión<input type="url" name="meeting_url" value="<?=e($v('meeting_url',($v('activity_type')==='meeting'?'https://www.socrates.la/meet':'')))?>" placeholder="https://www.socrates.la/meet"></label><label class="full">Detalles<textarea name="details"><?=e($v('details'))?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="activities.php">Cancelar</a><button class="btn btn-primary">GUARDAR ACTIVIDAD</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
